function Get-PestoRsaKeyBits {
    param($Key)
    if(-not $Key){return 0}
    try{$parameters=$Key.ExportParameters($false)}catch{return 0}
    if(-not $parameters){return 0}
    $modulus=$parameters.Modulus
    if($modulus -isnot [byte[]] -or $modulus.Length -lt 1){return 0}
    $offset=0
    while($offset -lt ($modulus.Length-1) -and $modulus[$offset] -eq 0){$offset++}
    return ($modulus.Length-$offset)*8
}
